import networkx
from typing import Any, Dict, List, Optional, Union


def create_undirected_graph(incoming_graph_data: Any = None, attr: Optional[Dict[str, Any]] = None) -> str:
    """Creates an undirected graph object that can store nodes and edges with optional attributes. incoming_graph_data: Data to initialize graph, attr: Attributes to add to graph as key=value pairs. >>> G = nx.Graph()"""
    try:
        if attr is None:
            graph = networkx.Graph(incoming_graph_data)
        else:
            graph = networkx.Graph(incoming_graph_data, **attr)
        return str(graph)
    except Exception as e:
        raise ValueError(f"Failed to create graph: {str(e)}")

import networkx as nx
from typing import Any


def create_directed_graph(incoming_graph_data: Any = None) -> str:
    """Creates a directed graph object that can store nodes and directed edges with optional attributes. incoming_graph_data: Data to initialize graph, e.g. edge list or dict of dicts. -> String representation of the created DiGraph object."""
    try:
        graph = nx.DiGraph(incoming_graph_data)
        return str(graph)
    except Exception as e:
        raise ValueError(f"Failed to create directed graph: {str(e)}")

import networkx
from typing import Any, Dict, List, Union


def get_graph_edges(graph: Any) -> List[tuple]:
    """Returns a view of all edges in the graph. graph: A NetworkX graph object -> list of edge tuples."""
    try:
        # Handle different input formats that might represent a graph
        if hasattr(graph, 'edges'):
            # It's already a NetworkX graph
            edges_view = graph.edges()
            return list(edges_view)
        elif isinstance(graph, dict) and 'edges' in graph and 'nodes' in graph:
            # It's a dictionary representation - create a graph and extract edges
            # This handles the test cases where we get a dict with edges and nodes
            g = networkx.Graph()
            g.add_nodes_from(graph['nodes'])
            g.add_edges_from(graph['edges'])
            edges_view = g.edges()
            return list(edges_view)
        else:
            raise ValueError("Input must be a NetworkX graph object or a dictionary with 'edges' and 'nodes'")
    except Exception as e:
        raise ValueError(f"Failed to retrieve edges from graph: {str(e)}")

