import networkx as nx


def create_petersen_graph(create_using: object | None = None) -> str:
    """Creates the Petersen Graph, a well-known symmetric graph with 10 vertices and 15 edges. create_using: Graph type to create. If graph instance, then cleared before populated. -> Graph as string representation."""
    try:
        graph = nx.petersen_graph(create_using=create_using)
        return f"Graph named '{graph.name}' with {graph.number_of_nodes()} nodes and {graph.number_of_edges()} edges"
    except Exception as e:
        raise ValueError(f"Failed to create Petersen Graph: {str(e)}")

import networkx


def compute_closeness_centrality(
    graph: object, 
    distance: str | None = None, 
    wf_improved: bool = True
) -> dict[str, float]:
    """Calculate the closeness centrality for all nodes in a graph based on shortest paths. graph: A NetworkX graph, distance: Edge attribute key to use as distance in shortest path calculations, wf_improved: If True, use Wasserman and Faust improved formula. -> Dictionary of nodes with closeness centrality as the value."""
    try:
        result = networkx.closeness_centrality(
            G=graph, 
            distance=distance, 
            wf_improved=wf_improved
        )
        return {str(node): float(value) for node, value in result.items()}
    except Exception as e:
        raise ValueError(f"Failed to compute closeness centrality: {str(e)}")

import networkx
from typing import Dict, Union, List, Any, Optional


def compute_clustering_coefficient(graph: object, nodes: Optional[List[Any]] = None, weight: Optional[str] = None) -> Union[float, Dict[str, float]]:
    """Compute the clustering coefficient for nodes in a graph, measuring how closely connected a node's neighbors are. graph: A NetworkX graph object. nodes: A list of nodes to compute clustering coefficients for. If None, computes for all nodes. weight: The edge attribute to use as weight. If None, all edges have weight 1. -> float or dict[str, float]
    """
    try:
        result = networkx.clustering(graph, nodes=nodes, weight=weight)
        if isinstance(result, dict):
            return {str(node): float(value) for node, value in result.items()}
        else:
            return float(result)
    except Exception as e:
        raise ValueError(f"Failed to compute clustering coefficient: {str(e)}")

import networkx
from typing import Optional, Union


def average_shortest_path_length(graph: networkx.Graph, weight: Optional[Union[str, callable]] = None, method: Optional[str] = None) -> float:
    """Returns the average shortest path length across all pairs of nodes. graph: A NetworkX graph. weight: Edge attribute to use as weight, or None for unit weights. method: Algorithm to use for computing path lengths."""
    try:
        return networkx.average_shortest_path_length(graph, weight=weight, method=method)
    except networkx.NetworkXError as e:
        raise ValueError(str(e)) from e
    except networkx.NetworkXPointlessConcept as e:
        raise ValueError(str(e)) from e

import networkx as nx
from networkx.algorithms.approximation import max_clique


def find_maximum_clique(graph: object) -> list[int]:
    """Find the Maximum Clique in a graph. graph: An undirected NetworkX graph -> The approximate maximum clique of the graph as a list of node indices."""
    try:
        clique = max_clique(graph)
        return sorted(list(clique))
    except Exception as e:
        if "NetworkXNotImplemented" in str(type(e)):
            raise ValueError("Graph must be undirected and not a multigraph") from e
        raise ValueError(f"Error finding maximum clique: {str(e)}") from e

import networkx as nx
from typing import List, Set, Optional


def find_infomap_communities(
    graph: object,
    weight: Optional[str] = "weight",
    seed: Optional[int] = None,
    num_trials: int = 1
) -> List[Set[int]]:
    """Find communities in a graph using the Infomap community detection algorithm. graph: A NetworkX graph (Graph, DiGraph, MultiGraph, or MultiDiGraph). weight: The name of an edge attribute holding the numerical weight. seed: Indicator of random number generation state. num_trials: Number of randomized searches. -> A list of sets of nodes representing the detected communities."""
    try:
        communities = list(nx.algorithms.community.infomap_communities(
            graph, weight=weight, seed=seed, num_trials=num_trials
        ))
        return [set(c) for c in communities]
    except Exception as e:
        if "num_trials" in str(e) and "positive integer" in str(e):
            raise ValueError("num_trials must be a positive integer")
        elif "teleportation_probability" in str(e) and "outside" in str(e):
            raise ValueError("teleportation_probability must be in the interval [0, 1]")
        elif "negative" in str(e) or "finite" in str(e):
            raise ValueError("All edge weights must be finite and non-negative")
        else:
            raise ValueError(f"Error running Infomap community detection: {str(e)}")

import networkx as nx
from typing import List, Tuple, Any


def check_tree_isomorphism(t1: Any, t2: Any) -> List[Tuple[Any, Any]]:
    """Determine if two trees are isomorphic to each other. t1: First undirected NetworkX graph representing a tree, t2: Second undirected NetworkX graph representing a tree. Returns a list of pairs mapping nodes from t1 to t2 if isomorphic, otherwise empty list."""
    try:
        result = nx.algorithms.isomorphism.tree_isomorphism(t1, t2)
        return result
    except nx.NetworkXError as e:
        raise ValueError(str(e))
